// Node connectivity: minimum size of a node set whose removal leaves the
// graph disconnected or with at most one node. The graphs here are tiny
// (<= 5 distinct nodes), so an exhaustive subset search matches
// nx.node_connectivity exactly (including kappa(K_n) = n - 1).

function* combinations(items, k, start = 0, prefix = []) {
  if (prefix.length === k) {
    yield prefix;
    return;
  }
  for (let i = start; i <= items.length - (k - prefix.length); i++) {
    yield* combinations(items, k, i + 1, [...prefix, items[i]]);
  }
}

function isConnectedOn(G, allowed) {
  if (allowed.size <= 1) return true;
  const start = allowed.values().next().value;
  const seen = new Set([start]);
  const stack = [start];
  while (stack.length > 0) {
    const v = stack.pop();
    for (const u of G.neighbors(v)) {
      if (allowed.has(u) && !seen.has(u)) {
        seen.add(u);
        stack.push(u);
      }
    }
  }
  return seen.size === allowed.size;
}

export function nodeConnectivity(G) {
  const nodes = G.nodes();
  const n = nodes.length;
  for (let k = 0; k <= n - 1; k++) {
    for (const subset of combinations(nodes, k)) {
      const removed = new Set(subset);
      const remaining = new Set(nodes.filter((x) => !removed.has(x)));
      if (remaining.size <= 1) return k;
      if (!isConnectedOn(G, remaining)) return k;
    }
  }
  return n - 1;
}

