// Python-style string formatting for print() output parity.

export function pyBool(b) {
  return b ? 'True' : 'False';
}

export function pyInt(n) {
  return String(n);
}

// Mirrors Python's str(float) for the values produced here:
// integral floats render as "5.0".
export function pyFloat(x) {
  if (Number.isInteger(x)) return `${x}.0`;
  return String(x);
}

export function pyTuple(items) {
  if (items.length === 1) return `(${items[0]},)`;
  return `(${items.join(', ')})`;
}

export function pyList(items) {
  return `[${items.join(', ')}]`;
}

