// Minimal argparse-compatible parser for: --a --b --c --d --e (type=int, required).
// Supports "--name value" and "--name=value" forms.

const NAMES = ['a', 'b', 'c', 'd', 'e'];

function fail(message) {
  console.error('usage: test10.mjs [-h] --a A --b B --c C --d D --e E');
  console.error(`test10.mjs: error: ${message}`);
  process.exit(2);
}

export function parseArgs(argv) {
  const values = {};
  const missing = new Set(NAMES);

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (!arg.startsWith('--')) {
      fail(`unrecognized arguments: ${arg}`);
    }
    let name;
    let raw;
    const eq = arg.indexOf('=');
    if (eq >= 0) {
      name = arg.slice(2, eq);
      raw = arg.slice(eq + 1);
    } else {
      name = arg.slice(2);
      raw = argv[++i];
    }
    if (!NAMES.includes(name)) {
      fail(`unrecognized arguments: ${arg}`);
    }
    if (raw === undefined) {
      fail(`argument --${name}: expected one argument`);
    }
    const trimmed = raw.trim();
    if (!/^[+-]?\d+$/.test(trimmed)) {
      fail(`argument --${name}: invalid int value: '${raw}'`);
    }
    values[name] = parseInt(trimmed, 10);
    missing.delete(name);
  }

  if (missing.size > 0) {
    fail(`the following arguments are required: ${[...missing].map((n) => `--${n}`).join(', ')}`);
  }
  return values;
}

