import { parseArgs } from './lib/args.mjs';
import { Graph } from './lib/graph.mjs';
import { minimumSpanningTree } from './lib/mst.mjs';
import { dijkstraPath, dijkstraPathLength } from './lib/dijkstra.mjs';
import { bfsEdges, dfsEdges } from './lib/traversal.mjs';
import { nodeConnectivity } from './lib/connectivity.mjs';
import { pyBool, pyFloat, pyInt, pyList, pyTuple } from './lib/pyformat.mjs';

const args = parseArgs(process.argv.slice(2));

const G = new Graph();
G.addWeightedEdgesFrom([
  [args.a, args.b, 1.0],
  [args.b, args.c, 2.0],
  [args.c, args.d, 3.0],
  [args.d, args.e, 4.0],
  [args.a, args.e, 5.0],
]);

console.log(pyInt(G.numberOfEdges())); // 获取边数量
console.log(pyFloat(G.getWeight(args.a, args.b))); // 获取边权重
